import React from 'react';
import { loginWithGoogle } from '../../services/api';

const Login = () => {
  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <div style={styles.iconContainer}>🍽️</div>
        <h1 style={styles.title}>Welcome Back</h1>
        <p style={styles.subtitle}>Sign in to reserve your perfect dining experience</p>
        <button onClick={loginWithGoogle} style={styles.googleButton}>
          <svg style={styles.googleIcon} viewBox="0 0 24 24">
            <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
            <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
            <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
            <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
          </svg>
          Continue with Google
        </button>
        <div style={styles.features}>
          <div style={styles.feature}>🥗 Convenience</div>
          <div style={styles.feature}>🔒 Secure & Safe</div>
          <div style={styles.feature}>🎉 Best Experience</div>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    minHeight: '100vh',
    background: '#667eea',
    fontFamily: "'Poppins', sans-serif",
  },
  card: {
    background: 'white',
    padding: '2.5rem 2rem',
    borderRadius: '20px',
    boxShadow: '0 15px 40px rgba(0,0,0,0.2)',
    textAlign: 'center',
    maxWidth: '400px',
    width: '100%',
  },
  iconContainer: {
    fontSize: '3rem',
    marginBottom: '1.5rem',
  },
  title: {
    fontSize: '2rem',
    marginBottom: '0.5rem',
    color: '#2d3748',
  },
  subtitle: {
    color: '#718096',
    marginBottom: '2rem',
    fontSize: '1rem',
  },
  googleButton: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '10px',
    width: '100%',
    padding: '1rem',
    border: '1px solid #e2e8f0',
    borderRadius: '12px',
    background: 'white',
    fontSize: '1rem',
    fontWeight: '600',
    cursor: 'pointer',
    color: '#2d3748',
    marginBottom: '1.5rem',
  },
  googleIcon: {
    width: '24px',
    height: '24px',
  },
  features: {
    display: 'flex',
    justifyContent: 'space-between',
    fontSize: '0.9rem',
    color: '#4a5568',
  },
  feature: {
    display: 'flex',
    alignItems: 'center',
    gap: '5px',
  },
};

export default Login;
